    <style>
        :root{--primary:#205bd7;--ink:#18243d;--muted:#7c8ba3;--line:#e8edf5;--surface:#fff;--bg:#f4f7fb;--success:#24a56a;--warning:#eaa52c;--danger:#d84c61}
        *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;min-height:100vh}
        body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.035;background-image:radial-gradient(#234b88 1px,transparent 1px);background-size:22px 22px}
        .shell{width:min(1440px,100%);margin:auto;padding:14px;position:relative}.card{background:rgba(255,255,255,.97);border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 30px rgba(39,63,98,.07)}
