        .stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:14px 0}.stat{padding:17px 18px;display:flex;align-items:center;gap:14px}.stat-icon{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;font-size:1.15rem}.stat:nth-child(1) .stat-icon{background:#eaf0ff;color:var(--primary)}.stat:nth-child(2) .stat-icon{background:#e7f8ef;color:var(--success)}.stat:nth-child(3) .stat-icon{background:#fff3dd;color:var(--warning)}.stat strong{font-size:1.35rem;display:block;line-height:1}.stat span{font-size:.75rem;color:var(--muted);display:block;margin-top:6px}
        .workspace{display:grid;grid-template-columns:minmax(360px,.92fr) minmax(420px,1.08fr);gap:14px}.panel{min-height:560px;overflow:hidden}.panel-head{height:55px;padding:0 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;font-size:.78rem;font-weight:800;letter-spacing:.08em}.panel-head i{color:var(--primary);margin-right:7px}.camera-state{border:0;font:inherit;font-size:.68rem;letter-spacing:0;color:var(--success);background:#e8f8ef;padding:7px 11px;border-radius:99px;cursor:pointer;font-weight:800}.camera-state.off{color:#b36b00;background:#fff3dd}.camera-wrap{padding:18px}.camera-stage{background:#fff;border-radius:15px;overflow:hidden;min-height:425px;display:grid;place-items:center;position:relative}#reader{width:100%;border:0!important;color:#8090a7} .camera-stage.active{background:#101826;color:#fff}.camera-placeholder{min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;text-align:center}.camera-placeholder i{font-size:3rem;color:#17243a}.camera-placeholder strong{font-size:.82rem;color:#34445e}.request-camera{border:0;border-radius:8px;background:#2362d5;color:#fff;padding:9px 14px;font-size:.7rem;font-weight:750;box-shadow:0 5px 12px #2362d533}.request-camera:hover{background:#174daf}.camera-placeholder small{font-size:.7rem;color:#8b98ab}.image-scan-link{font-size:.7rem;color:#2362d5;text-decoration:underline;cursor:pointer}#reader video{width:100%!important;max-height:425px;object-fit:cover;border-radius:14px}#reader__dashboard_section_csr button,#reader__dashboard_section_swaplink{border:0;border-radius:9px;padding:9px 12px;background:#fff;color:#18376d;font-weight:700}.scan-guide{display:flex;justify-content:center;align-items:center;gap:7px;color:var(--muted);font-size:.74rem;margin-top:13px}
