<main class="shell">
    <header class="card topbar">
        <div class="brand"><div class="logo">@if($school?->school_logo)<img src="{{asset('storage/'.$school->school_logo)}}" alt="Logo">@else<i class="bi bi-qr-code"></i>@endif</div><div class="brand-text"><strong>{{$school?->school_name ?: 'Sistem Absensi Siswa'}}</strong><small><span class="online">ONLINE</span> Mode Scan Absensi{{$class?->class_name ? ' - Kelas '.$class->class_name : ''}}</small></div></div>
