        <div class="card stat"><div class="stat-icon"><i class="bi bi-check-circle"></i></div><div><strong id="present">{{$present}}</strong><span>Hadir</span></div></div>
        <div class="card stat"><div class="stat-icon"><i class="bi bi-clock"></i></div><div><strong id="late">{{$late}}</strong><span>Terlambat</span></div></div>
    </section>
    <section class="workspace">
        <article class="card panel"><div class="panel-head"><span><i class="bi bi-qr-code-scan"></i>PEMINDAI QR</span><button type="button" class="camera-state" id="toggleScanner">MULAI SCAN</button></div><div class="camera-wrap"><div class="camera-stage"><div id="reader"><div class="camera-placeholder"><i class="bi bi-phone"></i><strong>Siap memindai kartu siswa</strong><button type="button" class="request-camera" onclick="document.getElementById('toggleScanner').click()">Request Camera Permissions</button><label class="image-scan-link" for="qrImageInput">Scan an Image File</label><input id="qrImageInput" type="file" accept="image/*" hidden></div></div></div><div class="scan-guide"><i class="bi bi-info-circle"></i> Arahkan QR kartu pelajar ke kamera</div></div></article>
        <article class="card panel result-panel"><div class="panel-head"><span><i class="bi bi-stars"></i>HASIL PRESENSI</span></div><div class="result-body" id="resultBody"><div class="result-empty"><i class="bi bi-person-bounding-box"></i><h2>Menunggu pemindaian</h2><p>Data siswa akan muncul otomatis setelah QR terbaca.</p></div></div></article>
    </section>
    <section class="card activity"><h3>Aktivitas Terbaru</h3><div class="activity-list" id="activity"><span class="empty-activity" id="emptyActivity">Belum ada scan pada sesi ini.</span></div></section>
</main>
