function scanned(token){const now=Date.now();if(locked||(scanCooldown.get(token)||0)>now)return;locked=true;scanCooldown.set(token,now+5000);fetch('{{route('attendance.scan.store')}}',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({token})}).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Scan gagal');const a=data.attendance;const student=a.student;const className=student.school_class?.class_name||'-';showResult('success',student.name,`${student.nis||'-'} · ${className}`,`${a.status} pukul ${a.check_in_time}`);document.getElementById('total').textContent=+document.getElementById('total').textContent+1;if(a.status==='hadir')document.getElementById('present').textContent=+document.getElementById('present').textContent+1;if(a.status==='terlambat')document.getElementById('late').textContent=+document.getElementById('late').textContent+1;document.getElementById('emptyActivity')?.remove();document.getElementById('activity').insertAdjacentHTML('afterbegin',`<div class="activity-item"><strong>${student.name}</strong><small>${className} · ${a.status} · ${a.check_in_time}</small></div>`);clearTimeout(resultTimer);resultTimer=setTimeout(()=>{document.getElementById('resultBody').innerHTML='<div class="result-empty"><i class="bi bi-person-bounding-box"></i><h2>Siap memindai siswa berikutnya</h2><p>Arahkan QR kartu pelajar ke kamera.</p></div>'},5000)}).catch(error=>{scanCooldown.delete(token);showResult('error','Scan tidak berhasil','Silakan periksa kartu dan coba kembali',error.message)}).finally(()=>{locked=false})}
const qrScanner=new Html5Qrcode('reader');function startScanning(){if(scanning)return;Html5Qrcode.getCameras().then(cameras=>{if(!cameras.length)throw new Error('Kamera tidak ditemukan');const camera=cameras.find(c=>/back|rear|environment/i.test(c.label))||cameras[0];activeCamera=camera.id;return qrScanner.start(camera.id,{fps:10,qrbox:{width:230,height:230},aspectRatio:1.15},scanned).then(()=>{scanning=true;document.querySelector('.camera-stage').classList.add('active');document.getElementById('toggleScanner').textContent='HENTIKAN SCAN'})}).catch(()=>{document.getElementById('reader').innerHTML='<div class="camera-placeholder"><i class="bi bi-camera-video-off"></i><strong>Izin kamera belum diberikan</strong><small>Izinkan kamera lalu klik tombol mulai lagi</small></div>'})}document.getElementById('qrImageInput').addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;qrScanner.scanFile(file,true).then(scanned).catch(()=>showResult('error','QR tidak terbaca','Pilih gambar kartu dengan QR yang jelas','Gambar QR tidak valid'));event.target.value='' });document.getElementById('toggleScanner').addEventListener('click',()=>{const button=document.getElementById('toggleScanner');if(scanning){qrScanner.stop().then(()=>{scanning=false;button.textContent='MULAI SCAN';button.classList.add('off');document.querySelector('.camera-stage').classList.remove('active');document.getElementById('reader').innerHTML='<div class="camera-placeholder"><i class="bi bi-phone"></i><strong>Siap memindai kartu siswa</strong><button type="button" class="request-camera" onclick="document.getElementById(\'toggleScanner\').click()">Request Camera Permissions</button><label class="image-scan-link" for="qrImageInput">Scan an Image File</label></div>';}).catch(()=>{})}else startScanning()});</script>
</body></html>




















